net.bsconfig:
{
  "rootDir": "<ROOT>",
  "files": [
    "manifest",
    "source/**/*",
    "components/**/*",
    {
      "src": "<ROOT>/.brighttest/headless/BT_config.brs",
      "dest": "source/bt/BT_config.brs"
    }
  ],
  "stagingDir": "<ROOT>/.brighttest/headless/build",
  "createPackage": false,
  "autoImportComponentScript": true,
  "diagnosticFilters": [
    1107
  ],
  "plugins": [
    "<REPO>/node_modules/@ramonlobo/rooibos-roku/dist/plugin.js",
    "<REPO>/lib/instrument/plugin.js"
  ],
  "instrument": {
    "net": true,
    "scene": false,
    "op": false,
    "netSpec": true
  },
  "rooibos": {
    "isRecordingCodeCoverage": false,
    "testsFilePattern": "**/*.spec.bs",
    "catchCrashes": false,
    "failFast": false,
    "tags": [
      "!deviceOnly"
    ]
  }
}

net.btConfig:
#if BT_AGENT
' brighttest instrument config. Generated for this build only; not part of the source tree.
function BT_config() as object
    return {
        token: "t0k"
        hub: { host: "127.0.0.1", port: 4000 }
        features: { net: true, state: false, op: false }
        caps: { depth: 6, arrayItems: 50, stringBytes: 2048 }
    }
end function
#end if

